-- Jeu de LecteurConvocations (« Convocations », PROC_GCONV), lot 7 du plan « RIG v3 100 % fonctionnel » (plan-676a4b19).
-- Identifiants 1 706 xxx, roles 2026J176xx. Les tables des audiences ont les MEMES definitions que dans PROC_RETAUD.sql ; les
-- tables de la LRAR et des relances, celles des jeux qui les creent deja (PROC_POOLEDITION.sql, PROC_RETOURLRAR.sql,
-- PROC_MDIL.sql), aux types de RIG_DEV ; seules les colonnes lues ici s'ajoutent, nullables. PAS d'IDENTITY.
-- Ce qui est retenu ou ecarte, et pourquoi : PROC_GCONV.attendu ; recherches : PROC_GCONV.recherches.
-- Lignes vues AUSSI par des ecrans qui lisent sans filtre (ajoutees a leur .attendu) : les demandes d'edition (PROC_POOLEDITION).
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
    CREATE TABLE v2.AUDIENCE_CABINET (AUDNC_ID_ADNC int NOT NULL PRIMARY KEY, AUDNC_DATE datetime NULL, AUDNC_HEURE varchar(5) NULL);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_AUDIENCE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_AUDIENCE bit NOT NULL DEFAULT (1);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_CHAMBRE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_CHAMBRE varchar(5) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_SECTION') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_SECTION varchar(10) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ID_JUG') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ID_JUG int NULL;
IF OBJECT_ID(N'v2.APPEL_AFFAIRE') IS NULL
    CREATE TABLE v2.APPEL_AFFAIRE (APPAF_ID_APPAF int NOT NULL PRIMARY KEY, APPAF_ID_INSTN int NULL, APPAF_NUM_ORDRE smallint NOT NULL,
        APPAF_ID_ADNC int NOT NULL);
IF OBJECT_ID(N'v2.CHAMBRE') IS NULL
    CREATE TABLE v2.CHAMBRE (R_CHAMBRE_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_CHAMBRE_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_CHAMBRE_AVEC_COMPO bit NOT NULL DEFAULT (1));
IF OBJECT_ID(N'v2.SECTION') IS NULL
    CREATE TABLE v2.SECTION (R_SECTION_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_SECTION_LIBELLE_ECRAN varchar(35) NOT NULL);
IF OBJECT_ID(N'v2.JUGE') IS NULL
    CREATE TABLE v2.JUGE (JUG_ID_JUG int NOT NULL PRIMARY KEY, JUG_CIVILITE varchar(7) NOT NULL, JUG_NOM varchar(35) NOT NULL, JUG_PRENOM varchar(20) NULL);
IF OBJECT_ID(N'v2.EVENEMENT_PROCEDURE') IS NULL
    CREATE TABLE v2.EVENEMENT_PROCEDURE (EVNPR_ID_EVNPR int NOT NULL PRIMARY KEY, EVNPR_ID_INSTN int NULL, EVNPR_NUM_ORDRE smallint NULL,
        EVNPR_CODE_EVE_PRO varchar(10) NOT NULL, EVNPR_DATE datetime NULL, EVNPR_SURVENU bit NULL, EVNPR_DELAI_EXPIRE bit NULL);
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_NUMERO_SOURCE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_TEXTE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_TEXTE varchar(max) NULL;
IF OBJECT_ID(N'v2.DEMANDE_EDITION') IS NULL
    CREATE TABLE v2.DEMANDE_EDITION (DMNED_ID_DMNED int NOT NULL PRIMARY KEY, DMNED_ID_DMND int NULL, DMNED_ID_DSRCS int NULL,
        DMNED_LOT varchar(255) NULL, DMNED_PHASE_TRAITEMENT varchar(10) NOT NULL, DMNED_DATE_PRE_EMISSION datetime NULL,
        DMNED_DESIGNATION_DESTINATAIRE varchar(255) NULL, DMNED_LIBELLE_DOCUMENT varchar(255) NOT NULL,
        DMNED_LIBELLE_ERREUR varchar(255) NULL, DMNED_DATE_CREATION datetime NULL, DMNED_ID_EMAIL_ENVOYE int NULL,
        DMNED_MODE_ENVOI int NULL);
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_NUM_LRAR') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_NUM_LRAR varchar(13) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_CODE_ENTITE_SOURCE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_CODE_ENTITE_SOURCE varchar(16) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_VALEUR_ID_SOURCE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_VALEUR_ID_SOURCE varchar(40) NULL;
IF OBJECT_ID(N'v2.LRAR_INFOS') IS NULL
    CREATE TABLE v2.LRAR_INFOS (LRARI_NUM_LRAR varchar(13) NOT NULL PRIMARY KEY, LRARI_DATE_RECEPTION datetime NULL,
        LRARI_TYPE varchar(15) NOT NULL, LRARI_TYPE_DATE varchar(20) NULL, LRARI_NUM_LRAR_RENVOYE varchar(13) NULL);
IF COL_LENGTH('v2.LRAR_INFOS', 'LRARI_SLN_CITATION') IS NULL ALTER TABLE v2.LRAR_INFOS ADD LRARI_SLN_CITATION bit NOT NULL DEFAULT (0);
IF OBJECT_ID(N'v2.PARAM_LRAR_INFOS') IS NULL
    CREATE TABLE v2.PARAM_LRAR_INFOS (PRMLI_CODE varchar(20) NOT NULL PRIMARY KEY, PRMLI_LIBELLE varchar(50) NULL,
        PRMLI_A_GERER bit NOT NULL);
IF OBJECT_ID(N'v2.DILIGENCE_RCS') IS NULL
    CREATE TABLE v2.DILIGENCE_RCS (DLGRC_ID_DLGRC int NOT NULL PRIMARY KEY, DLGRC_ID_ACTRC int NULL,
        DLGRC_NATURE_DILIGENCE varchar(10) NOT NULL, DLGRC_ETAT_DILIGENCE varchar(1) NULL, DLGRC_ETAT_RELANCE varchar(1) NULL);
IF OBJECT_ID(N'v2.RELANCE_RCS') IS NULL
    CREATE TABLE v2.RELANCE_RCS (RLCRC_ID_RLCRC int NOT NULL PRIMARY KEY, RLCRC_ID_DLGRC int NULL, RLCRC_NUM_ORDRE smallint NOT NULL,
        RLCRC_DATE_RELANCE datetime NOT NULL, RLCRC_DATE_LIMITE datetime NULL);
IF COL_LENGTH('v2.RELANCE_RCS', 'RLCRC_ID_INSTN') IS NULL ALTER TABLE v2.RELANCE_RCS ADD RLCRC_ID_INSTN int NULL;
IF OBJECT_ID(N'v2.EXERCICE') IS NULL
    CREATE TABLE v2.EXERCICE (EXRCC_ID_EXRCC int NOT NULL PRIMARY KEY, EXRCC_DATE_CLOTURE datetime NOT NULL);
IF COL_LENGTH('v2.EXERCICE', 'EXRCC_ID_DLGRC') IS NULL ALTER TABLE v2.EXERCICE ADD EXRCC_ID_DLGRC int NULL;

-- Les modalites de retour lues (libelles de RIG_DEV, les memes que PROC_RETOURLRAR.sql, qui les insere aussi sous condition).
INSERT INTO v2.PARAM_LRAR_INFOS (PRMLI_CODE, PRMLI_LIBELLE, PRMLI_A_GERER)
SELECT v.Code, v.Libelle, 1 FROM (VALUES ('NPAI', N'NPAI reçu le'), ('RECEPTION', N'Reçu le')) AS v (Code, Libelle)
WHERE NOT EXISTS (SELECT 1 FROM v2.PARAM_LRAR_INFOS AS p WHERE p.PRMLI_CODE = v.Code);

