-- LES GESTES (PROC_GCONV.gestes, EcrivainConvocations : « Citer par huissier »), joues APRES les .attendu et les recherches, sur les
-- lignes du cabinet 1706101 ci-dessus. La maquette du code CITATION a un destinataire huissier (« H,LRAR » apres un saut de ligne,
-- OPE_CITATIONS.cs:256-260) ; l'huissier 1706901 est un intervenant (INTERVENANT_PC_REPER). Tables lues par le seul geste.
IF OBJECT_ID(N'v2.CODE_EVE_PRO') IS NULL
    CREATE TABLE v2.CODE_EVE_PRO (R_CODEEVEPRO_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_CODEEVEPRO_LIBELLE_ECRAN varchar(35) NOT NULL);
